mapper.select:
select ifnull(sum(amount),0) from orders
where status=#{status} and checkout_time between #{begin} and #{end}

    and store_id = #{storeId}

select count(*) from orders
where status=#{status} and order_time between #{begin} and #{end}

    and store_id = #{storeId}

select count(*) from orders
where order_time between #{begin} and #{end}

    and store_id = #{storeId}

select count(*) from (
    select user_id, min(order_time) first_order_time
    from orders
    where store_id = #{storeId}
    group by user_id
) t
where t.first_order_time between #{begin} and #{end}

select od.name, sum(od.number) number from order_detail od left join orders o on od.order_id = o.id where o.order_time between #{begin} and #{end}
and o.store_id = #{storeId}
group by od.name order by number desc limit 10
